            data = (data << 1) | bit;
            bits_taken += 1;
            bit_index += 1;
        }
        const ones: u8 = std.mem.countBits(data);
        const parity: u8 = ones % 2;
        out[out_index] = (data << 1) | parity;
        out_index += 1;
    }
    return out;
