pub fn decodeMessage(allocator: mem.Allocator, message: []const u8) (mem.Allocator.Error || TransmissionError)![]u8 {
    if (message.len == 0) {
        return &[]u8{};
    }
    const total_data_bits: usize = message.len * 7;
    const out_len: usize = total_data_bits / 8;
    var out: ?[]u8 = null;
    if (out_len > 0) {
        out = try allocator.alloc(u8, out_len);
    }
    var out_index: usize = 0;
    var bit_buffer: u16 = 0;
    var bits_in_buffer: u8 = 0;
    for (message) |b| {
        if (std.mem.countBits(b) % 2 == 1) {
            if (out) |*ptr| {
                allocator.free(ptr);
            }
            return error.WrongParity;
        }
        var data: u8 = b >> 1;
        for (0..7) |i| {
            const bit: u8 = (data >> (6 - @intCast(u32, i))) & 1;
            bit_buffer = (bit_buffer << 1) | bit;
            bits_in_buffer += 1;
            if (bits_in_buffer == 8) {
                if (out) |*ptr| {
                    ptr[out_index] = @truncate(bit_buffer);
                }
                out_index += 1;
                bit_buffer = 0;
                bits_in_buffer = 0;
            }
        }
    }
    // If out_len==0, out is null, we just return empty slice.
    if (out) |*ptr| {
        return ptr;
    } else {
        return &[]u8{};
    }
}

